fn final_link(
    types: Vec<ResolvedTypeDeclaration>,
    mut facts: Facts,
    function: ResolvedFunction,
    old: bool,
) -> Result<ResolvedProgram, crate::diagnostic::Diagnostic> {
    facts.insert(
